import numpy as np


def construct(budget_seconds, start):
    """Code Zero: keep the start if there is one, otherwise a constant function (R = 2/3)."""
    if start is not None:
        return np.asarray(start, dtype=float)
    return np.ones(50)

import numpy as np
import time


def _score(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.all(h <= 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    c = np.convolve(h, h)
    L = np.concatenate(([0.0], c, [0.0]))
    L2 = L * L
    num = (2.0 * L2.sum() + np.dot(L[:-1], L[1:])) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return -1.0
    return num / den


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + max(0.0, budget_seconds - 2.0)

    def time_left():
        return deadline - time.process_time()

    best_h = None
    best_s = -1.0

    if start is not None:
        try:
            h0 = np.asarray(start, dtype=float).ravel()
            if h0.size > 0 and np.all(np.isfinite(h0)) and np.any(h0 > 0):
                s0 = _score(h0)
                if s0 > best_s:
                    best_s = s0
                    best_h = h0.copy()
        except Exception:
            pass

    rng = np.random.default_rng(2024)

    # Build candidate bumps. Autoconvolution of a bump tends to a triangle-like
    # shape; the "flat-top" family (1-|x|^p) with p ~ 1 gives a good start.
    def make_bump(N, p):
        x = np.linspace(-1.0, 1.0, N)
        return np.clip(1.0 - np.abs(x) ** p, 0.0, None)

    for N in [40, 80, 160, 320, 640, 1280, 2000]:
        for p in [0.6, 0.8, 1.0, 1.2, 1.5, 2.0, 2.5]:
            h = make_bump(N, p)
            if np.any(h > 0):
                s = _score(h)
                if s > best_s:
                    best_s = s
                    best_h = h

    if best_h is None:
        best_h = np.ones(50)
        best_s = _score(best_h)

    # Try upsampling the best bump to higher resolution (score is resolution-sensitive).
    def resample(h, N):
        xo = np.linspace(0, 1, h.size)
        xn = np.linspace(0, 1, N)
        return np.clip(np.interp(xn, xo, h), 0.0, None)

    for N in [200, 400, 800, 1600, 3200, 6400, 12800, 25000, 50000]:
        if time_left() <= 0:
            break
        h = resample(best_h, N) if best_h.size != N else best_h
        s = _score(h)
        if s > best_s:
            best_s = s
            best_h = h

    # Coordinate / block refinement: perturb a contiguous window with a smooth
    # multiplicative bump, which is efficient for this smooth objective.
    cur_h = best_h.copy()
    cur_s = best_s
    it = 0
    while time_left() > 0:
        it += 1
        n = cur_h.size
        # window size shrinks with iteration count
        w = max(1, int(n * max(0.02, 0.5 * (0.98 ** (it // 50)))))
        w = min(w, n)
        start_i = int(rng.integers(0, n - w + 1))
        scale = 0.1 * (0.95 ** (it // 100)) + 0.001
        cand = cur_h.copy()
        # smooth perturbation profile within window
        prof = np.sin(np.linspace(0, np.pi, w)) * rng.normal(0, scale)
        seg = cand[start_i:start_i + w]
        cand[start_i:start_i + w] = np.clip(seg + prof * (seg.max() + 1e-9), 0.0, None)
        if cand.sum() <= 0:
            continue
        s = _score(cand)
        if s > cur_s:
            cur_s = s
            cur_h = cand
            if s > best_s:
                best_s = s
                best_h = cand.copy()
        # occasionally restart from best
        if it % 400 == 0:
            cur_h = best_h.copy()
            cur_s = best_s

    best_h = np.clip(np.asarray(best_h, dtype=float), 0.0, None)
    if best_h.sum() <= 0:
        best_h = np.ones(50)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _L_of(h):
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L, c


def _R(h):
    h = np.asarray(h, dtype=float)
    L, c = _L_of(h)
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    C = np.max(L)
    if B <= 0 or C <= 0:
        return 0.0
    return A / (B * C)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    L, c = _L_of(h)
    n = c.size
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_soft_grad(h, tau):
    h = np.asarray(h, dtype=float)
    L, c = _L_of(h)
    n = c.size
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    Lmax = np.max(L)
    w = np.exp((L - Lmax) / tau)
    sw = np.sum(w)
    C = tau * (Lmax / tau + np.log(sw))
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    p = w / sw
    dC_c = p[1:-1]
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 1000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            xs = np.linspace(0.0, 1.0, s.size)
            xt = np.linspace(0.0, 1.0, N)
            h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-6)

    best_h = h0.copy()
    best_r = _R(h0)
    bounds = [(0.0, None)] * N

    def exact_polish(cur):
        def f(h):
            R, g = _R_grad(h)
            return -R, -g

        def cb(xk):
            if time.process_time() > deadline:
                raise _Timeout()

        try:
            res = minimize(f, cur, jac=True, method='L-BFGS-B',
                           bounds=bounds, callback=cb,
                           options={'ftol': 1e-16, 'gtol': 1e-14,
                                    'maxiter': 4000, 'maxcor': 30})
            return np.maximum(np.asarray(res.x, dtype=float), 0.0)
        except _Timeout:
            raise
        except Exception:
            return cur

    # Start: exact polish of interpolated start.
    try:
        cur = exact_polish(best_h)
        r = _R(cur)
        if r > best_r:
