    deadline = t0 + budget_seconds - 1.5

    N = 1000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = s.copy()
            else:
                xs = np.linspace(0.0, 1.0, s.size)
                xt = np.linspace(0.0, 1.0, N)
                h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-6)

    best_h = h0.copy()
    best_r = _R(h0)

    base_bounds = [(0.0, None)] * N

    Ks = [200, 100, 50, 30, 20, 15, 10, 7, 5, 3, 2]

    def _run(fun, cur, bounds, maxiter=3000):
        def cb(xk):
            if time.process_time() > deadline:
                raise _Timeout()
        res = minimize(fun, cur, jac=True, method='L-BFGS-B',
                       bounds=bounds, callback=cb,
                       options={'ftol': 1e-16, 'gtol': 1e-14,
                                'maxiter': maxiter, 'maxcor': 30})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def exact_polish(cur, bounds=None):
        if bounds is None:
            bounds = base_bounds
        def f(h):
            R, g = _R_grad(h)
            return -R, -g
        return _run(f, cur, bounds)

    def _neg_topk(h, K):
        R, g = _R_topk_grad(h, K)
        return -R, -g

    def topk_ladder(cur, Klist):
        for K in Klist:
            if time.process_time() > deadline:
                break
            try:
                cur = _run(lambda h, _K=K: _neg_topk(h, _K), cur, base_bounds)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    def support_search(cur, cur_r):
        """Try toggling boundary support indices on/off and reoptimize."""
        for _ in range(2):
            if time.process_time() > deadline:
                break
            mask = cur > 1e-8
            if mask.sum() == 0 or mask.sum() == N:
                break
            trans = np.flatnonzero(mask[1:] != mask[:-1]) + 1
            if trans.size == 0:
                break
            cand_idx = set()
            for t in trans:
                for d in range(-3, 4):
                    j = t + d
                    if 0 <= j < N:
                        cand_idx.add(j)
            cand_idx = sorted(cand_idx)[:20]
            if not cand_idx:
                break
            hmax = np.max(cur)
            improved = False
            best_cand = cur
            best_cand_r = cur_r
            for i in cand_idx:
                if time.process_time() > deadline:
                    break
                # (a) turn off
                if mask[i]:
                    b_off = list(base_bounds)
                    b_off[i] = (0.0, 0.0)
                    c = cur.copy()
                    c[i] = 0.0
                    try:
                        c = exact_polish(c, b_off)
                        r = _R(c)
                    except _Timeout:
                        break
                    except Exception:
                        r = -1
                    if r > best_cand_r:
                        best_cand_r = r
                        best_cand = c.copy()
                        improved = True
                # (b) turn on
                else:
                    c = cur.copy()
                    c[i] = 1e-6 * hmax
                    try:
                        c = exact_polish(c, base_bounds)
                        r = _R(c)
                    except _Timeout:
                        break
                    except Exception:
                        r = -1
                    if r > best_cand_r:
                        best_cand_r = r
                        best_cand = c.copy()
                        improved = True
            if improved:
                cur = best_cand
                cur_r = best_cand_r
            else:
                break
        return cur, cur_r

    rng = np.random.default_rng(246813579)

    # Warm start
    try:
        cur = exact_polish(best_h)
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print("warm improved", best_r)
    except Exception:
        pass

    cur = best_h.copy()
    no_improve = 0
    cycle = 0

    while time.process_time() < deadline:
        cycle += 1
        prev_r = best_r

        try:
            cur = exact_polish(cur)
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print("exact improved", best_r, "cycle", cycle)

        if time.process_time() > deadline:
            break

        # Support local search after exact polish
        try:
            cur, r = support_search(cur, r)
            if r > best_r:
                best_r = r
                best_h = cur.copy()
                print("support improved", best_r, "cycle", cycle)
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() > deadline:
            break

        try:
            cur = topk_ladder(cur, Ks)
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print("topk improved", best_r, "cycle", cycle)

        if time.process_time() > deadline:
            break

        try:
            cur = exact_polish(cur)
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print("exact2 improved", best_r, "cycle", cycle)

        if time.process_time() > deadline:
            break

        # Support local search after exact2
        try:
            cur, r = support_search(cur, r)
            if r > best_r:
                best_r = r
                best_h = cur.copy()
                print("support2 improved", best_r, "cycle", cycle)
        except _Timeout:
            break
        except Exception:
            pass

        if best_r <= prev_r + 1e-13:
            no_improve += 1
        else:
            no_improve = 0

        if no_improve >= 1:
            best_trial = best_h
            best_trial_r = best_r
            L = _knots(best_h)
            C = np.max(L)
            plateau = (L > C * (1.0 - 5e-4)).astype(float)
            w = np.correlate(plateau[1:-1], np.ones(N), 'valid')
            w = w / (np.max(w) + 1e-30)
            for scale in (1e-5, 5e-5, 2e-4):
                if time.process_time() > deadline:
                    break
                noise = rng.standard_normal(N) * w
                cand = best_h * np.exp(scale * noise)
                cand = np.maximum(cand, 1e-9)
                cand = cand * (np.sum(best_h) / np.sum(cand))
                try:
                    cx = topk_ladder(cand, [50, 20, 10, 5, 3, 2])
                    cx = exact_polish(cx)
                    cr = _R(cx)
                except Exception:
                    cx = cand
                    cr = _R(cand)
                if cr > best_trial_r:
                    best_trial_r = cr
                    best_trial = cx
            if best_trial_r > best_r:
                best_r = best_trial_r
                best_h = best_trial.copy()
                print("perturb improved", best_r, "cycle", cycle)
            cur = best_h.copy()
            no_improve = 0

    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _knots(h):
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    C = np.max(L)
    if B <= 0 or C <= 0:
        return 0.0
    return A / (B * C)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    L = _knots(h)
    n = L.size - 2
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    L = _knots(h)
    n = L.size - 2
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(n)
    sel = idx[(idx >= 1) & (idx <= n)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


