                cur = _run(lambda h, _K=K: _neg_topk(h, _K), cur, base_bounds)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    BLOCK_LENS = (1, 2, 3, 5, 8, 13)

    def block_search(cur, cur_r):
        """Toggle contiguous blocks at each support transition, then polish."""
        for _ in range(2):
            if time.process_time() > deadline:
                break
            mask = cur > 1e-8
            if mask.sum() == 0 or mask.sum() == N:
