                    if t - 1 >= 0 and not mask[t - 1]:
                        lo = max(0, t - L); hi = t
                        candidates.append(('on', lo, hi))
                    # block into nonzero side (off): rightward from t
                    if t < N and mask[t]:
                        lo = t; hi = min(N, t + L)
                        candidates.append(('off', lo, hi))
                    # block into nonzero side (off): leftward ending at t
                    if t - 1 >= 0 and mask[t - 1]:
