                else:
                    c[lo:hi] = 0.0
                try:
                    c = exact_polish(c)
                    r = _R(c)
                except _Timeout:
                    break
                except Exception:
                    continue
                if r > best_cand_r:
                    best_cand_r = r
                    best_cand = c.copy()
                    improved = True
            if improved:
                cur = best_cand
                cur_r = best_cand_r
            else:
                break
        return cur, cur_r

