        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print("warm improved", best_r)
    except Exception:
        pass

    cur = best_h.copy()
    no_improve = 0
    cycle = 0

    while time.process_time() < deadline:
        cycle += 1
        prev_r = best_r

        try:
            cur = exact_polish(cur)
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print("exact improved", best_r, "cycle", cycle)

        if time.process_time() > deadline:
            break

        # Block support local search after exact polish
        try:
            cur, r = block_search(cur, r)
            if r > best_r:
                best_r = r
                best_h = cur.copy()
                print("block improved", best_r, "cycle", cycle)
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() > deadline:
            break

        try:
            cur = topk_ladder(cur, Ks)
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print("topk improved", best_r, "cycle", cycle)

        if time.process_time() > deadline:
