def _penalty_grad(h, mu):
    """F(h) = -A/B + mu*sum(relu(L-1)^2), with L scaled so max(L)=1 at entry.
    Returns (F, dF/dh)."""
    h = np.asarray(h, dtype=float)
    L = _knots(h)
    n = L.size - 2
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    r = np.maximum(L - 1.0, 0.0)
    P = np.sum(r * r)
    F = -A / B + mu * P
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dF = -(dA / B - A * dB / (B * B))
    if P > 0:
        r_c = r[1:-1]
        dP = 2.0 * np.correlate(r_c, h, 'valid')
        dF = dF + mu * dP
    return F, dF


