                print("perturb improved", best_r, "cycle", cycle)
            cur = best_h.copy()
            no_improve = 0

    # ---- New stage: direct max(L)<=1 penalty optimizer ----
    if time.process_time() < deadline:
        try:
            h = best_h.copy()
            L = _knots(h)
            C = np.max(L)
