    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.interpolate import BSpline


def _R(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    C = np.max(L)
    if B <= 0 or C <= 0:
        return 0.0
    return A / (B * C)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1; m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0; L[-1] = 0.0; L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(n)
    sel = idx[(idx >= 1) & (idx <= n)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    N = 1000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = s.copy()
            else:
                xs = np.linspace(0.0, 1.0, s.size)
                xt = np.linspace(0.0, 1.0, N)
                h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-6)

    best_h = h0.copy()
    best_r = _R(h0)
    bounds = [(0.0, None)] * N

    def _run(fun, cur, bnds, maxiter=3000):
        def cb(xk):
            if time.process_time() > deadline:
                raise _Timeout()
        res = minimize(fun, cur, jac=True, method='L-BFGS-B',
                       bounds=bnds, callback=cb,
                       options={'ftol': 1e-16, 'gtol': 1e-14,
                                'maxiter': maxiter, 'maxcor': 30})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def exact_polish(cur, bnds=None):
        if bnds is None:
            bnds = bounds
        def f(h):
            R, g = _R_grad(h)
            return -R, -g
        return _run(f, cur, bnds)

    def topk_ladder(cur, Klist):
        for K in Klist:
            if time.process_time() > deadline:
                break
            def neg(h, _K=K):
                R, g = _R_topk_grad(h, _K)
                return -R, -g
            try:
                cur = _run(neg, cur, bounds)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    # Spline smoothing in control space (helps escape flat plateaus)
    def spline_polish(cur, K_ctrl=200):
        try:
            n_inner = max(0, K_ctrl - 4)
            if n_inner > 0:
                k = np.arange(n_inner + 2)
                m = n_inner + 2
                cheb = 0.5 * (1.0 - np.cos(np.pi * k / (m - 1)))
                interior = cheb[1:-1]
            else:
                interior = np.array([])
            knots = np.concatenate([np.zeros(4), interior, np.ones(4)])
            t = np.linspace(0.0, 1.0, N)
            B = np.zeros((N, K_ctrl))
            for i in range(K_ctrl):
                c = np.zeros(K_ctrl); c[i] = 1.0
                spl = BSpline(knots, c, 3, extrapolate=True)
                B[:, i] = spl(t)
            B = np.maximum(B, 0.0)
            c0 = np.maximum(np.linalg.lstsq(B, cur, rcond=None)[0], 1e-9)
            def neg(c):
                h = B @ c
                R, g = _R_grad(h)
                return -R, -(B.T @ g)
            def cb(xk):
                if time.process_time() > deadline:
                    raise _Timeout()
            res = minimize(neg, c0, jac=True, method='L-BFGS-B',
                           bounds=[(0.0, None)] * K_ctrl, callback=cb,
                           options={'ftol': 1e-16, 'gtol': 1e-14,
                                    'maxiter': 1500, 'maxcor': 30})
            c_opt = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            h_s = np.maximum(B @ c_opt, 0.0)
            return h_s
        except _Timeout:
            return cur
        except Exception:
            return cur

    # Warm start
    try:
        cur = exact_polish(best_h)
        r = _R(cur)
        if r > best_r:
            best_r = r; best_h = cur.copy()
            print("warm improved", best_r)
    except Exception:
        pass

    cur = best_h.copy()
    cycle = 0

    while time.process_time() < deadline:
        cycle += 1
        prev_r = best_r

        # Spline escape
        if cycle % 2 == 1:
            try:
                hs = spline_polish(cur, K_ctrl=180)
                rs = _R(hs)
                if rs > prev_r - 1e-12:
                    cur = hs
            except Exception:
                pass

        try:
            cur = exact_polish(cur)
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r; best_h = cur.copy()
            print("exact improved", best_r, "cycle", cycle)

        if time.process_time() > deadline:
            break

        try:
            cur = topk_ladder(cur, [100, 50, 30, 20, 15, 10, 7, 5, 3, 2])
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r; best_h = cur.copy()
            print("topk improved", best_r, "cycle", cycle)

        if time.process_time() > deadline:
            break

        try:
            cur = exact_polish(cur)
        except _Timeout:
            break
        except Exception:
            pass
        r = _R(cur)
        if r > best_r:
            best_r = r; best_h = cur.copy()
            print("exact2 improved", best_r, "cycle", cycle)

        if best_r <= prev_r + 1e-13:
            # perturb with plateau-weighted noise
            rng = np.random.default_rng(1000 + cycle)
            L = np.convolve(best_h, best_h)
            C = np.max(L)
            plateau = (L > C * (1.0 - 5e-4)).astype(float)
            w = np.correlate(plateau, np.ones(N), 'valid')
            w = w / (np.max(w) + 1e-30)
            for scale in (2e-5, 1e-4, 4e-4):
                if time.process_time() > deadline:
                    break
                noise = rng.standard_normal(N) * w
                cand = best_h * np.exp(scale * noise)
                cand = np.maximum(cand, 1e-9)
                cand = cand * (np.sum(best_h) / np.sum(cand))
                try:
                    cx = topk_ladder(cand, [30, 10, 5, 3, 2])
                    cx = exact_polish(cx)
                    cr = _R(cx)
                except Exception:
                    cx = cand; cr = _R(cand)
                if cr > best_r:
                    best_r = cr; best_h = cx.copy()
                    print("perturb improved", best_r, "cycle", cycle)
                    cur = best_h.copy()
                    break
            else:
                # restart from spline perturb
                try:
                    hs = spline_polish(best_h, K_ctrl=250)
                    cur = exact_polish(hs)
                except Exception:
                    cur = best_h.copy()

    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
