    def _run_length(mask, t, side):
        # side: 'right' -> run starting at t going right; 'left' -> run ending at t-1 going left
        n = mask.size
        if side == 'right':
            i = t
            while i < n and mask[i] == mask[t]:
                i += 1
            return i - t
        else:
            i = t - 1
            while i >= 0 and mask[i] == mask[t - 1]:
                i -= 1
            return t - 1 - i

