        mask = base_h > 1e-8
        if mask.all() or not mask.any():
            return
        trans = np.where(mask[1:] != mask[:-1])[0] + 1
        if trans.size == 0:
            return
        cands = []
        hmax = float(np.max(base_h))
        for t in trans:
            # run length on the side being toggled
            if mask[t]:
                # nonzero side to the right of t -> we will zero a block; run is right run
                R = _run_length(mask, t, 'right')
            else:
                # zero side to the right of t -> we will fill; run is right run of zeros
                R = _run_length(mask, t, 'right')
