        cands = []
        hmax = float(np.max(base_h))
        for t in trans:
            for L in TOGGLE_Ls:
                if mask[t]:
                    lo = t; hi = min(N, t + L)
                else:
                    lo = max(0, t - L); hi = t
                if hi > lo:
                    c1 = base_h.copy()
                    c1[lo:hi] = 0.0
                    if np.any(c1 > 0):
                        cands.append(c1)
                if not mask[t]:
                    lo = t; hi = min(N, t + L)
                    if t > 0 and mask[t - 1]:
                        val = base_h[t - 1]
                    elif t < N and mask[t]:
                        val = base_h[t]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                else:
                    lo = max(0, t - L); hi = t
                    if hi < N and mask[hi]:
                        val = base_h[hi]
                    elif lo > 0 and mask[lo - 1]:
                        val = base_h[lo - 1]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                if len(cands) >= 40:
                    break
            if len(cands) >= 40:
                break

        best_c = None
        best_cr = best_r
        for cand in cands:
            if time.process_time() > deadline:
                break
            try:
                cx = topk_ladder(cand, TOGGLE_Ks)
                cx = exact_polish(cx)
                cr = _R(cx)
            except _Timeout:
                break
            except Exception:
                continue
            if cr > best_cr:
                best_cr = cr
                best_c = cx
        if best_c is not None:
            best_h = best_c.copy()
            best_r = best_cr
            print("toggle improved", best_r)

    # Phase 1: warm exact polish
    try:
        cur = exact_polish(best_h)
        try_update(cur, "warm exact improved")
    except Exception:
        pass

    # Phase 2: flattening attempts
    for tol in (1e-2, 3e-3, 1e-3, 3e-4):
        if time.process_time() > deadline:
            break
        try:
            flat = flatten_plateau(best_h, tol)
            flat = np.maximum(flat, 1e-9)
            cx = topk_ladder(flat, TOGGLE_Ks)
            cx = exact_polish(cx)
            try_update(cx, "flatten %.0e" % tol)
        except _Timeout:
            break
        except Exception:
            pass

    # Phase 3: toggle search on the current best
    if time.process_time() <= deadline:
        try:
            toggle_search(best_h)
        except _Timeout:
            pass
        except Exception:
            pass

    # Phase 4: final exact polish of the best
    if time.process_time() <= deadline:
        try:
            cur = exact_polish(best_h)
            try_update(cur, "final polish")
        except Exception:
            pass

    print("final best R", best_r, "N", N)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_softmax_grad(h, ntop, beta):
    """Smooth surrogate: ||f*f||_inf replaced by softmax over top ntop knots."""
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    ntop = min(ntop, L.size)
    idx = np.argpartition(L, -ntop)[-ntop:]
    Ltop = L[idx]
    mx = np.max(Ltop)
    w = np.exp(beta * (Ltop - mx))
    sw = np.sum(w)
    C = mx + np.log(sw) / beta
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    wn = w / sw
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    # map back weights
    selmask = (idx >= 1) & (idx <= c.size)
    dC_c[idx[selmask] - 1] = wn[selmask]
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


