import numpy as np
import time
from scipy.optimize import minimize


def _R(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_pen(h, eps=1e-2, lam=1e-3):
    """Penalised objective: -A/B + lam * variance of top plateau / C^2."""
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    C = float(np.max(L))
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    mask = L >= (1.0 - eps) * C
    K = int(mask.sum())
    if K < 2:
        R, g = _R_grad(h)
        return -R, -g
    m = float(L[mask].mean())
    P = float(((L[mask] - m) ** 2).mean()) / (C * C)
    F = -A / B + lam * P

    # dA/dh
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)

    # dC/dh (max knot)
    k = int(np.argmax(L))
    dC = np.zeros_like(h)
    j = k - 1
    mm = len(h)
    lo = max(0, j - (mm - 1)); hi = min(mm - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]

    # dP/dh
    dP_c = np.zeros(c.size)
    sel = np.where(mask[1:n + 1])[0]  # interior knot indices j -> c index j-1
    if sel.size > 0:
        dP_c[sel] = 2.0 * (L[sel + 1] - m) / (K * C * C)
    dP = 2.0 * np.correlate(dP_c, h, 'valid') + (-2.0 * P / C) * dC

    grad = -dA / B + A * dB / (B * B) + lam * dP
    return F, grad


