            try:
                # symmetrize candidate, take half
                cand_sym = 0.5 * (cand + cand[::-1])
                cg = np.maximum(cand_sym[:M], 0.0)
                cg = topk_ladder(cg, TOGGLE_Ks)
                cg = exact_polish(cg)
                cr = R_g(cg)
