        mask = L >= (1.0 - tol) * mx
        hmask = np.zeros_like(h, dtype=bool)
        idx = np.where(mask)[0]
        for j in idx:
            if 1 <= j <= h.size:
                hmask[j - 1] = True
        if not hmask.any():
