    def coord_ascent(base_h, rounds, step_fracs):
        nonlocal best_h, best_r
        h = base_h.copy()
        r = _R(h)
        n = h.size
        for rnd in range(rounds):
            if time.process_time() > deadline:
                break
            improved = False
            order = np.argsort(-h)
            for idx in order:
                if time.process_time() > deadline:
                    break
                old = h[idx]
                if old <= 1e-12:
