                for sf in step_fracs:
                    for sign in (1.0, -1.0):
                        trial = h.copy()
                        nv = old * (1.0 + sign * sf)
                        if nv < 0:
                            nv = 0.0
                        trial[idx] = nv
                        tr = _R(trial)
                        if tr > r + 1e-15:
                            h = trial
                            r = tr
                            improved = True
