def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    # Symmetric representation: h has N=2000 steps, g = h[:m] with m=1000,
    # and h = concat(g, g[::-1]).  R(h) == R(g) under this symmetry.
    m = 1000
    N = 2 * m

    def expand(g):
        g = np.maximum(np.asarray(g, dtype=float), 0.0)
        return np.concatenate([g, g[::-1]])

    def _R_g(g):
        return _R(expand(g))

    def _R_grad_g(g):
        # gradient wrt g of R(expand(g)): chain rule through the symmetry.
        h = expand(g)
        R, gh = _R_grad(h)
        gg = gh[:m] + gh[m:][::-1]
        return R, gg

    def _R_topk_grad_g(g, K):
        h = expand(g)
        R, gh = _R_topk_grad(h, K)
        gg = gh[:m] + gh[m:][::-1]
        return R, gg

    # Build starting g from `start`
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
