    best_r = _R_g(g0)
    print("start R (sym N=%d)" % N, best_r)

    bounds = [(0.0, None)] * m

    def exact_polish(cur):
        def neg_R_grad(g):
            R, gr = _R_grad_g(g)
            return -R, -gr
        res = minimize(neg_R_grad, cur, jac=True, method='L-BFGS-B',
