import numpy as np
import time
from scipy.optimize import minimize
from scipy.sparse.linalg import cg


def _L(h):
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _L(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _plateau_penalty_grad(h, tol=1e-3):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    C = float(np.max(L))
    if C <= 0:
        return 0.0, np.zeros_like(h)
    mask = L >= (1.0 - tol) * C
    K = int(mask.sum())
    if K <= 1:
        return 0.0, np.zeros_like(h)
    Lm = L[mask]
    mean = Lm.mean()
    var = np.mean((Lm - mean) ** 2)
    P = var / (C * C)
    q = np.zeros_like(L)
    q[mask] = 2.0 * (Lm - mean) / K
    q_int = q[1:-1]
    dP = 2.0 * np.correlate(q_int, h, 'valid')
    return P, dP


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 2000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = np.maximum(s.astype(float).copy(), 0.0)
            else:
                xs = np.linspace(0.0, 1.0, s.size)
                xt = np.linspace(0.0, 1.0, N)
                h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-9)
    if h0.sum() <= 0:
        h0 = np.ones(N)
    h0 = 0.5 * (h0 + h0[::-1])
    h0 = np.maximum(h0, 0.0)

    best_h = h0.copy()
    best_r = _R(h0)
    print("start R", best_r, "N", N)

    bounds = [(0.0, None)] * N

    def exact_polish(cur):
        def neg_R_grad(h):
            R, g = _R_grad(h)
            return -R, -g
        res = minimize(neg_R_grad, cur, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       options={'ftol': 1e-18, 'gtol': 1e-15,
                                'maxiter': 5000, 'maxcor': 40})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def topk_ladder(cur, Ks):
        for K in Ks:
            if time.process_time() > deadline:
                break

            def neg_topk_grad(h, _K=K):
                R, g = _R_topk_grad(h, _K)
                return -R, -g

            def callback(xk):
                if time.process_time() > deadline:
                    raise _Timeout()

            try:
                res = minimize(neg_topk_grad, cur, jac=True, method='L-BFGS-B',
                               bounds=bounds, callback=callback,
                               options={'ftol': 1e-18, 'gtol': 1e-15,
                                        'maxiter': 3000, 'maxcor': 40})
                cur = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    def try_update(cur, tag):
        nonlocal best_h, best_r
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print(tag, best_r)
            return True
        return False

    def flatten_plateau(h, tol=1e-3):
        L = _L(h)
        mx = float(np.max(L))
        if mx <= 0:
            return h
        mask = L >= (1.0 - tol) * mx
        hmask = np.zeros_like(h, dtype=bool)
        idx = np.where(mask)[0]
        for j in idx:
            if 1 <= j <= h.size:
                hmask[j - 1] = True
        if not hmask.any():
            return h
        out = h.copy()
        i = 0
        n = h.size
        while i < n:
            if hmask[i]:
                j = i
                while j + 1 < n and hmask[j + 1]:
                    j += 1
                seg = out[i:j + 1]
                s = seg.sum()
                if s > 0:
                    out[i:j + 1] = s / seg.size
                i = j + 1
            else:
                i += 1
        return out

    def plateau_equalize(h, tol):
        """Gauss-Newton step to equalize near-max knots of L."""
        h = np.asarray(h, dtype=float)
        c = np.convolve(h, h)
        n = c.size
        L = np.empty(n + 2)
        L[0] = 0.0
        L[-1] = 0.0
        L[1:-1] = c
        C = float(np.max(L))
        if C <= 0:
            return h
        mask = L >= (1.0 - tol) * C
        # exclude endpoints (indices 0 and n+1)
        mask[0] = False
        mask[-1] = False
        idx = np.where(mask)[0]
        if idx.size < 2:
            return h
        Lm = L[idx]
        mean = Lm.mean()
        r = Lm - mean
        # J delta = 2 * convolve(delta, h)[idx-1]
        # J^T y = 2 * correlate(y_int, h, 'valid') with y_int[idx-1] = y
        m = h.size

        def matvec(delta):
            conv = np.convolve(delta, h)
            return 2.0 * conv[idx - 1]

        def rmatvec(y):
            y_int = np.zeros(n, dtype=float)
            y_int[idx - 1] = y
            return 2.0 * np.correlate(y_int, h, 'valid')

        from scipy.sparse.linalg import LinearOperator
        J = LinearOperator((idx.size, m), matvec=matvec, rmatvec=rmatvec,
                           dtype=float)
        # Normal equations: (J^T J + reg I) delta = -J^T r
        def A_op(delta):
            return J.rmatvec(J.matvec(delta)) + 1e-6 * delta

        b = -J.rmatvec(r)
        A = LinearOperator((m, m), matvec=A_op, dtype=float)
        try:
            delta, info = cg(A, b, maxiter=200, rtol=1e-10, atol=0.0)
        except Exception:
            return h
        if not np.all(np.isfinite(delta)):
            return h
        out = np.maximum(h + delta, 0.0)
        return out

