    assert len(best_h) == N
    assert _R(best_h) >= _R(h0) - 1e-12

    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _L(h):
    c = fftconvolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _L(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * fftconvolve(dC_c, h[::-1], 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_softmax_grad(h, beta):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    z = beta * L
    zmax = np.max(z)
    e = np.exp(z - zmax)
    s = e.sum()
    C = (zmax + np.log(s)) / beta
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    w = e / s
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    w_int = w[1:-1]
    dC = 2.0 * fftconvolve(w_int, h[::-1], 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _plateau_penalty_grad(h, tol=1e-3):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    C = float(np.max(L))
    if C <= 0:
        return 0.0, np.zeros_like(h)
    mask = L >= (1.0 - tol) * C
    K = int(mask.sum())
    if K <= 1:
        return 0.0, np.zeros_like(h)
    Lm = L[mask]
    mean = Lm.mean()
    var = np.mean((Lm - mean) ** 2)
    P = var / (C * C)
    q = np.zeros_like(L)
    q[mask] = 2.0 * (Lm - mean) / K
    q_int = q[1:-1]
    dP = 2.0 * fftconvolve(q_int, h[::-1], 'valid')
    return P, dP


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 4000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = np.maximum(s.astype(float).copy(), 0.0)
            else:
                xs = np.linspace(0.0, 1.0, s.size)
                xt = np.linspace(0.0, 1.0, N)
                h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-9)
    if h0.sum() <= 0:
        h0 = np.ones(N)

    best_h = h0.copy()
    best_r = _R(h0)
    print("start R", best_r, "N", N)

    bounds = [(0.0, None)] * N

    def exact_polish(cur):
        def neg_R_grad(h):
            R, g = _R_grad(h)
            return -R, -g
        res = minimize(neg_R_grad, cur, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       options={'ftol': 1e-18, 'gtol': 1e-15,
                                'maxiter': 5000, 'maxcor': 40})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def softmax_polish(cur, beta):
        def neg_R_grad(h):
            R, g = _R_softmax_grad(h, beta)
            return -R, -g

        def callback(xk):
            if time.process_time() > deadline:
                raise _Timeout()
        try:
            res = minimize(neg_R_grad, cur, jac=True, method='L-BFGS-B',
                           bounds=bounds, callback=callback,
                           options={'ftol': 1e-20, 'gtol': 1e-16,
                                    'maxiter': 4000, 'maxcor': 50})
            return np.maximum(np.asarray(res.x, dtype=float), 0.0)
        except _Timeout:
            raise
        except Exception:
            return cur

    def topk_ladder(cur, Ks):
        for K in Ks:
            if time.process_time() > deadline:
                break

            def neg_topk_grad(h, _K=K):
                R, g = _R_topk_grad(h, _K)
                return -R, -g

            def callback(xk):
                if time.process_time() > deadline:
                    raise _Timeout()

            try:
                res = minimize(neg_topk_grad, cur, jac=True, method='L-BFGS-B',
                               bounds=bounds, callback=callback,
                               options={'ftol': 1e-18, 'gtol': 1e-15,
                                        'maxiter': 3000, 'maxcor': 40})
                cur = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    def try_update(cur, tag):
        nonlocal best_h, best_r
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print(tag, best_r)
            return True
        return False

    def flatten_plateau(h, tol=1e-3):
        L = _L(h)
        mx = float(np.max(L))
        if mx <= 0:
            return h
        mask = L >= (1.0 - tol) * mx
        hmask = np.zeros_like(h, dtype=bool)
        idx = np.where(mask)[0]
        for j in idx:
            if 1 <= j <= h.size:
                hmask[j - 1] = True
        if not hmask.any():
            return h
        out = h.copy()
        i = 0
        n = h.size
        while i < n:
            if hmask[i]:
                j = i
                while j + 1 < n and hmask[j + 1]:
                    j += 1
                seg = out[i:j + 1]
                s = seg.sum()
                if s > 0:
                    out[i:j + 1] = s / seg.size
                i = j + 1
            else:
                i += 1
        return out

    try:
        cur = exact_polish(best_h)
        try_update(cur, "warm exact improved")
    except Exception:
        pass

    # Softmax continuation: smooths the max so gradient flows through all
    # near-maximal knots, escaping the argmax discontinuity trap.
    try:
        cur = best_h.copy()
        for beta in (5.0, 20.0, 80.0, 300.0, 1000.0, 3000.0):
            if time.process_time() > deadline:
                break
            cur = softmax_polish(cur, beta)
        cur = exact_polish(cur)
        try_update(cur, "softmax-continuation improved")
    except _Timeout:
        pass
    except Exception:
        pass

    def plateau_penalty_polish(cur, lam):
        def neg_F_grad(h):
            R, gR = _R_grad(h)
            P, gP = _plateau_penalty_grad(h, tol=1e-3)
            F = -R + lam * P
            g = -gR + lam * gP
            return F, g

        def callback(xk):
            if time.process_time() > deadline:
                raise _Timeout()

        try:
            res = minimize(neg_F_grad, cur, jac=True, method='L-BFGS-B',
                           bounds=bounds, callback=callback,
                           options={'ftol': 1e-18, 'gtol': 1e-15,
                                    'maxiter': 2000, 'maxcor': 40})
            return np.maximum(np.asarray(res.x, dtype=float), 0.0)
        except _Timeout:
            raise
        except Exception:
            return cur

    for lam in (1e-3, 1e-2, 1e-1):
        if time.process_time() > deadline:
            break
        try:
            cand = plateau_penalty_polish(best_h.copy(), lam)
            cand = exact_polish(cand)
            try_update(cand, "plateau-var improved (lam=%g)" % lam)
        except _Timeout:
            break
        except Exception:
            pass

    for tol in (1e-2, 3e-3, 1e-3, 3e-4):
        if time.process_time() > deadline:
            break
        try:
            fh = flatten_plateau(best_h, tol)
            fh = topk_ladder(fh, [min(800, N), min(480, N), min(320, N), min(200, N),
                                  min(100, N), min(48, N), min(24, N), min(12, N), min(6, N), min(3, N)])
            fh = exact_polish(fh)
            try_update(fh, "flatten improved (tol=%g)" % tol)
        except _Timeout:
            break
        except Exception:
            pass

    Ks_big = [min(k, N) for k in
              [1600, 1320, 1040, 800, 600, 480, 400, 320, 240, 200, 160, 120, 100,
               80, 60, 50, 40, 30, 25, 20, 15, 12, 10, 8, 7, 6, 5, 4, 3, 2]]

    rng = np.random.default_rng(20240611)
    cycle = 0
    no_improve = 0

    while time.process_time() < deadline:
        cycle += 1
        prev_r = best_r

        try:
            cur = topk_ladder(best_h.copy(), Ks_big)
            try_update(cur, "topk improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() > deadline:
            break
        try:
            cur = exact_polish(best_h.copy())
            try_update(cur, "exact improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() < deadline:
            try:
                cur = best_h.copy()
                for beta in (50.0, 200.0, 800.0, 2500.0):
                    if time.process_time() > deadline:
                        break
                    cur = softmax_polish(cur, beta)
                cur = exact_polish(cur)
                try_update(cur, "softmax cycle improved")
            except _Timeout:
                break
            except Exception:
                pass

        if time.process_time() < deadline:
            for tol in (1e-2, 1e-3):
                if time.process_time() > deadline:
                    break
                try:
                    fh = flatten_plateau(best_h, tol)
                    fh = topk_ladder(fh, [min(600, N), min(320, N), min(160, N),
                                          min(80, N), min(40, N), min(20, N), min(10, N), min(4, N)])
                    fh = exact_polish(fh)
                    try_update(fh, "flatten cycle improved (tol=%g)" % tol)
                except _Timeout:
                    break
                except Exception:
                    pass

        if best_r <= prev_r + 1e-15:
            no_improve += 1
        else:
            no_improve = 0

        if no_improve >= 1 and time.process_time() < deadline:
            best_trial = best_h
            best_trial_r = best_r
            for scale in (1e-7, 1e-6, 1e-5):
                if time.process_time() > deadline:
                    break
                cand = best_h * np.exp(scale * rng.standard_normal(N))
                cand = np.maximum(cand, 1e-9)
                cand = cand * (np.sum(best_h) / np.sum(cand))
                try:
                    cx = topk_ladder(cand, [min(400, N), min(200, N), min(100, N),
                                            min(50, N), min(25, N), min(12, N), min(7, N), min(4, N)])
                    cx = exact_polish(cx)
                    cr = _R(cx)
                except Exception:
                    cx = cand
                    cr = _R(cand)
                if cr > best_trial_r:
                    best_trial_r = cr
                    best_trial = cx
            if best_trial_r > best_r:
                best_r = best_trial_r
                best_h = best_trial.copy()
                print("perturb improved", best_r, "cycle", cycle)
            no_improve = 0

    try:
        if time.process_time() < deadline:
            sym = 0.5 * (best_h + best_h[::-1])
            sym = np.maximum(sym, 0.0)
            if sym.sum() > 0:
                sym = topk_ladder(sym, [min(800, N), min(480, N), min(320, N),
                                        min(200, N), min(100, N), min(48, N),
                                        min(24, N), min(12, N), min(6, N), min(3, N)])
                sym = flatten_plateau(sym, 1e-2)
                sym = exact_polish(sym)
                sr = _R(sym)
                if sr > best_r:
                    best_r = sr
                    best_h = sym.copy()
                    print("final symmetrize improved", best_r)
    except _Timeout:
        pass
    except Exception:
        pass

    try:
        for tol in (2e-2, 1e-2, 3e-3, 1e-3, 3e-4, 1e-4):
            if time.process_time() > deadline:
                break
            fh = flatten_plateau(best_h, tol)
            fh = topk_ladder(fh, [min(480, N), min(240, N), min(120, N), min(60, N),
                                  min(30, N), min(15, N), min(8, N), min(4, N)])
            fh = exact_polish(fh)
            try_update(fh, "final flatten tol=%g" % tol)
    except _Timeout:
        pass
    except Exception:
        pass

    if _R(best_h) < _R(h0):
        best_h = h0.copy()
        best_r = _R(h0)

    assert len(best_h) == N
    assert _R(best_h) >= _R(h0) - 1e-12

    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize


def _L(h):
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _L(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    # Use the size of the incoming start when possible (it is already tuned).
    N = 1000
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0:
            N = int(s.size)

    # Build initial full h (symmetrized).
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = np.maximum(s.astype(float).copy(), 0.0)
            else:
                xs = np.linspace(0.0, 1.0, s.size)
                xt = np.linspace(0.0, 1.0, N)
                h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-9)
    if h0.sum() <= 0:
        h0 = np.ones(N)

    start_R = _R(h0)

    # Work in full (non-symmetric) space but symmetrize at end via mirror trick:
    # we optimize over half g, h = [g, g[::-1]] which guarantees symmetry.
    m = (N + 1) // 2

    def h_of(g):
        if N % 2 == 0:
            return np.concatenate([g, g[::-1]])
        else:
            return np.concatenate([g, g[-2::-1]])

    def _R_sym(g):
        return _R(h_of(g))

    def _R_grad_sym(g):
        R, gh = _R_grad(h_of(g))
        if N % 2 == 0:
            return R, gh[:m] + gh[m:][::-1]
        else:
            return R, gh[:m] + np.concatenate([[0.0], gh[m:][::-1]])

    def _R_topk_grad_sym(g, K):
        R, gh = _R_topk_grad(h_of(g), K)
        if N % 2 == 0:
            return R, gh[:m] + gh[m:][::-1]
        else:
            return R, gh[:m] + np.concatenate([[0.0], gh[m:][::-1]])

    # symmetrize start
    sym = 0.5 * (h0 + h0[::-1])
    sym = np.maximum(sym, 1e-9)
    g = sym[:m].copy()
    best_g = g.copy()
    best_r = _R_sym(g)
    best_h_full = h_of(best_g).copy()
    best_r_full = best_r
    print("start R", start_R, "sym R", best_r)

    bounds = [(0.0, None)] * m

    def exact_polish_sym(cur_g):
        def neg_R_grad(g_):
            R, gr = _R_grad_sym(g_)
            return -R, -gr
        res = minimize(neg_R_grad, cur_g, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       options={'ftol': 1e-18, 'gtol': 1e-15,
                                'maxiter': 5000, 'maxcor': 40})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def topk_ladder_sym(cur_g, Ks):
        for K in Ks:
            if time.process_time() > deadline:
                break

            def neg_topk_grad(g_, _K=K):
                R, gr = _R_topk_grad_sym(g_, _K)
                return -R, -gr

            def callback(xk):
                if time.process_time() > deadline:
                    raise _Timeout()

            try:
                res = minimize(neg_topk_grad, cur_g, jac=True, method='L-BFGS-B',
                               bounds=bounds, callback=callback,
                               options={'ftol': 1e-18, 'gtol': 1e-15,
                                        'maxiter': 3000, 'maxcor': 40})
                cur_g = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            except _Timeout:
                break
            except Exception:
                pass
        return cur_g

    def try_update_sym(cur_g, tag):
