            cur_g = exact_polish_sym(best_g.copy())
            try_update_sym(cur_g, "exact improved")
        except _Timeout:
            break
        except Exception:
            pass

        if best_r <= prev_r + 1e-15:
            no_improve += 1
        else:
            no_improve = 0

        if no_improve >= 1 and time.process_time() < deadline:
            best_trial = best_g
            best_trial_r = best_r
            for scale in (1e-8, 1e-7, 3e-7, 1e-6, 3e-6):
                if time.process_time() > deadline:
                    break
                cand = best_g * np.exp(scale * rng.standard_normal(m))
                cand = np.maximum(cand, 1e-9)
                if cand.sum() <= 0:
                    continue
                cand = cand * (np.sum(best_g) / np.sum(cand))
                try:
                    cx = topk_ladder_sym(cand, [100, 50, 25, 12, 7, 4, 2])
                    cx = exact_polish_sym(cx)
                    cr = _R_sym(cx)
                except Exception:
                    cx = cand
                    cr = _R_sym(cand)
                if cr > best_trial_r:
