import numpy as np
import time
from scipy.optimize import minimize


def _L(h):
    c = np.convolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _L(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * np.correlate(dC_c, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_softmax_grad(h, beta):
    h = np.asarray(h, dtype=float)
    c = np.convolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    z = beta * L
    zmax = np.max(z)
    e = np.exp(z - zmax)
    s = e.sum()
    C = (zmax + np.log(s)) / beta
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    w = e / s
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * np.correlate(g_c, h, 'valid')
    dB = 2.0 * np.sum(h)
    w_int = w[1:-1]
    dC = 2.0 * np.correlate(w_int, h, 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 1000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = np.maximum(s.astype(float).copy(), 0.0)
            else:
                xs = np.linspace(0.0, 1.0, s.size)
                xt = np.linspace(0.0, 1.0, N)
                h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-9)
    if h0.sum() <= 0:
        h0 = np.ones(N)

    best_h = h0.copy()
    best_r = _R(h0)
    print("start R", best_r)

    bounds = [(0.0, None)] * N

    def exact_polish(cur):
        def neg_R_grad(h):
            R, g = _R_grad(h)
            return -R, -g
        res = minimize(neg_R_grad, cur, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       options={'ftol': 1e-18, 'gtol': 1e-15,
                                'maxiter': 5000, 'maxcor': 40})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def softmax_polish(cur, beta):
        def neg_R_grad(h):
            R, g = _R_softmax_grad(h, beta)
            return -R, -g
        def callback(xk):
            if time.process_time() > deadline:
                raise _Timeout()
        try:
            res = minimize(neg_R_grad, cur, jac=True, method='L-BFGS-B',
                           bounds=bounds, callback=callback,
                           options={'ftol': 1e-20, 'gtol': 1e-16,
                                    'maxiter': 4000, 'maxcor': 50})
            return np.maximum(np.asarray(res.x, dtype=float), 0.0)
        except _Timeout:
            raise
        except Exception:
            return cur

    def topk_ladder(cur, Ks):
        for K in Ks:
            if time.process_time() > deadline:
                break

            def neg_topk_grad(h, _K=K):
                R, g = _R_topk_grad(h, _K)
                return -R, -g

            def callback(xk):
                if time.process_time() > deadline:
                    raise _Timeout()

            try:
                res = minimize(neg_topk_grad, cur, jac=True, method='L-BFGS-B',
                               bounds=bounds, callback=callback,
                               options={'ftol': 1e-18, 'gtol': 1e-15,
                                        'maxiter': 3000, 'maxcor': 40})
                cur = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    def try_update(cur, tag):
        nonlocal best_h, best_r
        r = _R(cur)
        if r > best_r:
            best_r = r
            best_h = cur.copy()
            print(tag, best_r)
            return True
        return False

    def flatten_plateau(h, tol=1e-3):
        L = _L(h)
        mx = float(np.max(L))
        if mx <= 0:
            return h
        mask = L >= (1.0 - tol) * mx
        hmask = np.zeros_like(h, dtype=bool)
        idx = np.where(mask)[0]
        for j in idx:
            if 1 <= j <= h.size:
                hmask[j - 1] = True
        if not hmask.any():
            return h
        out = h.copy()
        i = 0
        n = h.size
        while i < n:
            if hmask[i]:
                j = i
                while j + 1 < n and hmask[j + 1]:
                    j += 1
                seg = out[i:j + 1]
                s = seg.sum()
                if s > 0:
                    out[i:j + 1] = s / seg.size
                i = j + 1
            else:
                i += 1
        return out

    try:
        cur = exact_polish(best_h)
        try_update(cur, "warm exact improved")
    except Exception:
        pass

    # softmax continuation
    try:
        cur = best_h.copy()
        for beta in (5.0, 20.0, 80.0, 300.0, 1000.0, 3000.0):
            if time.process_time() > deadline:
                break
            cur = softmax_polish(cur, beta)
            _ = _R(cur)
        cur = exact_polish(cur)
        try_update(cur, "softmax-continuation improved")
    except _Timeout:
        pass
    except Exception:
        pass

    Ks_big = [400, 330, 260, 200, 150, 120, 100, 80, 60, 50, 40, 30, 25, 20,
              15, 12, 10, 8, 7, 6, 5, 4, 3, 2]

    rng = np.random.default_rng(20240611)
    cycle = 0

    scales = (1e-6, 3e-6, 1e-5, 3e-5, 1e-4, 3e-4, 1e-3)
    small_Ks = [80, 40, 20, 10, 5, 3, 2]
    # NEW: mid-K ladder focused on the plateau (K near plateau width ~200-300)
    plateau_Ks = [300, 250, 220, 200, 180, 160, 140, 120, 100, 80]

    while time.process_time() < deadline:
        cycle += 1
        improved = False
        base = best_h.copy()

        if cycle % 3 == 1:
            for tol in (1e-2, 3e-3, 1e-3):
                if time.process_time() > deadline:
                    break
                try:
                    fh = flatten_plateau(base, tol)
                    fh = topk_ladder(fh, [200, 120, 80, 50, 25, 12, 6, 3, 2])
                    fh = exact_polish(fh)
                    if try_update(fh, "flatten improved (tol=%g)" % tol):
                        improved = True
                        break
                except _Timeout:
                    break
                except Exception:
                    pass

        if time.process_time() > deadline:
            break

        # NEW: plateau-band topk tightening — the top ~200 knots dominate
        # linf, so polishing with K in that band directly attacks flattening.
        if cycle % 2 == 1:
            try:
                cur = topk_ladder(best_h.copy(), plateau_Ks)
                cur = exact_polish(cur)
                if try_update(cur, "plateau-band improved"):
                    improved = True
            except _Timeout:
                break
            except Exception:
                pass

        if time.process_time() > deadline:
            break

        if cycle % 2 == 0:
            try:
                cur = best_h.copy()
                for beta in (10.0, 50.0, 200.0, 800.0, 2500.0):
                    if time.process_time() > deadline:
                        break
                    cur = softmax_polish(cur, beta)
                cur = exact_polish(cur)
                if try_update(cur, "softmax improved"):
                    improved = True
            except _Timeout:
                break
            except Exception:
                pass

        if time.process_time() > deadline:
            break

        trials = 0
        while time.process_time() < deadline and trials < 4:
            trials += 1
            scale = scales[(trials + cycle) % len(scales)]
            cand = base * np.exp(scale * rng.standard_normal(N))
            cand = np.maximum(cand, 1e-12)
            s = np.sum(cand)
            if s <= 0:
                continue
            cand = cand * (np.sum(base) / s)
            try:
                cx = topk_ladder(cand, small_Ks)
                cx = exact_polish(cx)
                cr = _R(cx)
            except _Timeout:
                break
            except Exception:
                continue
            if cr > best_r:
                best_r = cr
                best_h = cx.copy()
                improved = True
                print("perturb improved", best_r, "cycle", cycle, "scale", scale)

        if time.process_time() > deadline:
            break

        if not improved and cycle % 2 == 0:
            try:
                cur = topk_ladder(best_h.copy(), Ks_big)
                try_update(cur, "topk improved")
            except _Timeout:
                break
            except Exception:
                pass

        if time.process_time() > deadline:
            break
        if not improved and cycle % 4 == 0:
            try:
                cur = exact_polish(best_h.copy())
                try_update(cur, "exact improved")
            except _Timeout:
                break
            except Exception:
                pass

    try:
        if time.process_time() < deadline:
            sym = 0.5 * (best_h + best_h[::-1])
            sym = np.maximum(sym, 0.0)
            if sym.sum() > 0:
                sym = topk_ladder(sym, [200, 120, 80, 50, 25, 12, 6, 3, 2])
                sym = exact_polish(sym)
                sr = _R(sym)
                if sr > best_r:
                    best_r = sr
                    best_h = sym.copy()
                    print("final symmetrize improved", best_r)
    except _Timeout:
        pass
    except Exception:
        pass

    try:
        if time.process_time() < deadline:
            cur = exact_polish(best_h.copy())
            try_update(cur, "final exact improved")
    except Exception:
        pass

    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

