    # Higher N gives finer resolution but per-iteration cost grows ~ N log N.
    # We keep N=2000 (matches start) and rely on a better search.
    N = 2000
    M = N // 2

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = np.maximum(s.astype(float).copy(), 0.0)
            else:
                xs = np.linspace(0.0, 1.0, s.size)
                xt = np.linspace(0.0, 1.0, N)
                h0 = np.interp(xt, xs, s)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-9)
    if h0.sum() <= 0:
        h0 = np.ones(N)
    h0 = 0.5 * (h0 + h0[::-1])
    h0 = np.maximum(h0, 0.0)

    # half-space parameterization: g of length M, full h = [g, g[::-1]]
    def expand(g):
        g = np.maximum(np.asarray(g, dtype=float), 0.0)
        return np.concatenate([g, g[::-1]])

    def R_g(g):
        return _R(expand(g))

    def R_grad_g(g):
        h = expand(g)
        R, gh = _R_grad(h)
        gg = gh[:M] + gh[::-1][:M]
        return R, gg

    def R_topk_grad_g(g, K):
        h = expand(g)
        R, gh = _R_topk_grad(h, K)
        gg = gh[:M] + gh[::-1][:M]
        return R, gg

    g0 = h0[:M].copy()
    best_g = g0.copy()
    best_h = expand(best_g)
    best_r = _R(best_h)
    print("start R", best_r)

    bounds = [(0.0, None)] * M

    def exact_polish(cur_g):
        def neg_R_grad(g):
            R, gr = R_grad_g(g)
            return -R, -gr
        res = minimize(neg_R_grad, cur_g, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       options={'ftol': 1e-18, 'gtol': 1e-15,
                                'maxiter': 4000, 'maxcor': 40})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def topk_ladder(cur_g, Ks):
        for K in Ks:
            if time.process_time() > deadline:
                break

            def neg_topk_grad(g, _K=K):
                R, gr = R_topk_grad_g(g, _K)
                return -R, -gr

            def callback(xk):
                if time.process_time() > deadline:
                    raise _Timeout()

            try:
                res = minimize(neg_topk_grad, cur_g, jac=True, method='L-BFGS-B',
                               bounds=bounds, callback=callback,
                               options={'ftol': 1e-18, 'gtol': 1e-15,
                                        'maxiter': 2000, 'maxcor': 40})
                cur_g = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            except _Timeout:
                break
            except Exception:
                pass
        return cur_g

    def try_update(cur_g, tag):
        nonlocal best_g, best_h, best_r
        h = expand(cur_g)
        r = _R(h)
        if r > best_r + 1e-15:
            best_r = r
            best_g = cur_g.copy()
            best_h = h.copy()
            print(tag, best_r)
            return True
        return False

    def flatten_plateau_g(g, tol=1e-3):
        h = expand(g)
        L = _L(h)
        mx = float(np.max(L))
        if mx <= 0:
            return g
        mask = L >= (1.0 - tol) * mx
        hmask = np.zeros_like(h, dtype=bool)
        idx = np.where(mask)[0]
        for j in idx:
            if 1 <= j <= h.size:
                hmask[j - 1] = True
        if not hmask.any():
            return g
        out = h.copy()
        i = 0
        n = h.size
        while i < n:
            if hmask[i]:
                j = i
                while j + 1 < n and hmask[j + 1]:
                    j += 1
                seg = out[i:j + 1]
                s = seg.sum()
                if s > 0:
                    out[i:j + 1] = s / seg.size
                i = j + 1
            else:
                i += 1
        out = 0.5 * (out + out[::-1])
        return out[:M].copy()

    def toggle_search(base_g):
        nonlocal best_g, best_h, best_r
        base_h = expand(base_g)
        mask = base_h > 1e-8
        if mask.all() or not mask.any():
            return
        trans = np.where(mask[1:] != mask[:-1])[0] + 1
        if trans.size == 0:
            return
        cands = []
        hmax = float(np.max(base_h))
        TOGGLE_Ls = [2, 4, 6, 10, 16, 26, 42]
        for t in trans:
            for L in TOGGLE_Ls:
                if mask[t]:
                    lo = t; hi = min(N, t + L)
                else:
                    lo = max(0, t - L); hi = t
                if hi > lo:
                    c1 = base_h.copy()
                    c1[lo:hi] = 0.0
                    if np.any(c1 > 0):
                        cands.append(c1)
                if not mask[t]:
                    lo = t; hi = min(N, t + L)
                    if t > 0 and mask[t - 1]:
                        val = base_h[t - 1]
                    elif t < N and mask[t]:
                        val = base_h[t]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                else:
                    lo = max(0, t - L); hi = t
                    if hi < N and mask[hi]:
                        val = base_h[hi]
                    elif lo > 0 and mask[lo - 1]:
                        val = base_h[lo - 1]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                if len(cands) >= 30:
                    break
            if len(cands) >= 30:
                break

        best_c = None
        best_cr = best_r
        for cand in cands:
            if time.process_time() > deadline:
                break
            try:
                cand_sym = 0.5 * (cand + cand[::-1])
                cg = np.maximum(cand_sym[:M], 0.0)
                cg = topk_ladder(cg, [200, 120, 60, 30, 14, 8, 4, 2])
                cg = exact_polish(cg)
                cr = R_g(cg)
            except _Timeout:
                break
            except Exception:
                continue
            if cr > best_cr:
                best_cr = cr
                best_c = cg
        if best_c is not None:
            best_g = best_c.copy()
            best_h = expand(best_g)
            best_r = best_cr
            print("toggle improved", best_r)

    # Main loop: alternate topk ladder, exact polish, plateau flatten, toggles.
    Ks_big = [700, 560, 440, 340, 260, 200, 150, 110, 80, 60, 44, 32, 24,
              18, 13, 10, 8, 6, 5, 4, 3, 2]

    rng = np.random.default_rng(1234567)
    cycle = 0
    no_improve = 0
    prev_r = best_r

    while time.process_time() < deadline:
        cycle += 1
        prev_r = best_r

        try:
            cur = topk_ladder(best_g.copy(), Ks_big)
            try_update(cur, "topk improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() > deadline:
            break

        try:
            cur = exact_polish(best_g.copy())
            try_update(cur, "exact improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() < deadline:
            for tol in (1e-2, 3e-3, 1e-3):
                if time.process_time() > deadline:
                    break
                try:
                    fg = flatten_plateau_g(best_g, tol)
                    fg = topk_ladder(fg, [240, 140, 80, 44, 24, 12, 6, 3, 2])
                    fg = exact_polish(fg)
                    try_update(fg, "flatten improved (tol=%g)" % tol)
                except _Timeout:
                    break
                except Exception:
                    pass

        if time.process_time() < deadline:
            try:
                toggle_search(best_g.copy())
            except _Timeout:
                break
            except Exception:
                pass

        if best_r <= prev_r + 1e-15:
            no_improve += 1
        else:
            no_improve = 0

        # Perturbation when stuck
        if no_improve >= 2 and time.process_time() < deadline:
            best_trial_g = best_g
            best_trial_r = best_r
            for scale in (1e-8, 1e-7, 3e-7, 1e-6, 3e-6, 1e-5):
                if time.process_time() > deadline:
                    break
                cand = best_g * np.exp(scale * rng.standard_normal(M))
                cand = np.maximum(cand, 1e-9)
                ssum = np.sum(cand)
                if ssum > 0:
                    cand = cand * (np.sum(best_g) / ssum)
                try:
                    cg = topk_ladder(cand, [180, 90, 44, 22, 12, 6, 3, 2])
                    cg = exact_polish(cg)
                    cr = R_g(cg)
                except Exception:
                    cg = cand
                    cr = R_g(cand)
                if cr > best_trial_r:
                    best_trial_r = cr
                    best_trial_g = cg
            if best_trial_r > best_r + 1e-15:
                best_r = best_trial_r
                best_g = best_trial_g.copy()
                best_h = expand(best_g)
                print("perturb improved", best_r, "cycle", cycle)
            no_improve = 0

    # Final polish
    try:
        if time.process_time() < deadline:
            fg = topk_ladder(best_g.copy(), [400, 240, 140, 80, 44, 24, 12, 6, 3, 2])
            fg = flatten_plateau_g(fg, 1e-2)
            fg = exact_polish(fg)
            sr = R_g(fg)
            if sr > best_r:
                best_r = sr
                best_g = fg.copy()
                best_h = expand(best_g)
                print("final polish improved", best_r)
            else:
                print("final polish no gain", sr, "vs", best_r)
    except _Timeout:
        pass
    except Exception:
        pass

    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _L(h):
    c = fftconvolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _L(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * fftconvolve(dC_c, h[::-1], 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _plateau_penalty_grad(h, tol=1e-3):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    C = float(np.max(L))
    if C <= 0:
        return 0.0, np.zeros_like(h)
    mask = L >= (1.0 - tol) * C
    K = int(mask.sum())
    if K <= 1:
        return 0.0, np.zeros_like(h)
    Lm = L[mask]
    mean = Lm.mean()
    var = np.mean((Lm - mean) ** 2)
    P = var / (C * C)
    q = np.zeros_like(L)
    q[mask] = 2.0 * (Lm - mean) / K
    q_int = q[1:-1]
    dP = 2.0 * fftconvolve(q_int, h[::-1], 'valid')
    return P, dP


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 6000

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = np.maximum(s.astype(float).copy(), 0.0)
            else:
                # piecewise-constant replication
                j = np.arange(N)
                src = np.minimum(s.size - 1, (j * s.size) // N)
                h0 = np.maximum(s[src].astype(float), 0.0)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 1e-9)
    if h0.sum() <= 0:
