    if C <= 0:
        return 0.0, np.zeros_like(h)
    mask = L >= (1.0 - tol) * C
    K = int(mask.sum())
    if K <= 1:
        return 0.0, np.zeros_like(h)
    Lm = L[mask]
    mean = Lm.mean()
    var = np.mean((Lm - mean) ** 2)
    P = var / (C * C)
    q = np.zeros_like(L)
    q[mask] = 2.0 * (Lm - mean) / K
    q_int = q[1:-1]
    dP = 2.0 * fftconvolve(q_int, h[::-1], 'valid')
    return P, dP


