import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _L(h):
    c = fftconvolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _L(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * fftconvolve(dC_c, h[::-1], 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _plateau_penalty_grad(h, tol=1e-3):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    C = float(np.max(L))
    if C <= 0:
        return 0.0, np.zeros_like(h)
    mask = L >= (1.0 - tol) * C
    K = int(mask.sum())
    if K <= 1:
        return 0.0, np.zeros_like(h)
    Lm = L[mask]
    mean = Lm.mean()
    var = np.mean((Lm - mean) ** 2)
    P = var / (C * C)
    q = np.zeros_like(L)
    q[mask] = 2.0 * (Lm - mean) / K
    q_int = q[1:-1]
    dP = 2.0 * fftconvolve(q_int, h[::-1], 'valid')
    return P, dP


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 8000
    m = N // 2

    def h_of(g):
        return np.concatenate([g, g[::-1]])

    def R_sym(g):
        return _R(h_of(g))

    def R_grad_sym(g):
        R, gh = _R_grad(h_of(g))
        return R, gh[:m] + gh[m:][::-1]

    def R_topk_grad_sym(g, K):
        R, gh = _R_topk_grad(h_of(g), K)
        return R, gh[:m] + gh[m:][::-1]

    def plateau_penalty_grad_sym(g, tol=1e-3):
        P, gh = _plateau_penalty_grad(h_of(g), tol)
        return P, gh[:m] + gh[m:][::-1]

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            sN = s.size
            idx = np.minimum((np.arange(N) * sN) // N, sN - 1)
            h0 = s[idx].astype(float).copy()
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        h0 = np.array([min(i + 1, N - i) for i in range(N)], dtype=float)
    h0 = np.maximum(h0, 0.0)
    h0 = 0.5 * (h0 + h0[::-1])
    if h0.sum() <= 0:
        h0 = np.ones(N)
    g0 = np.maximum(h0[:m].copy(), 1e-9)

    best_g = g0.copy()
    best_r = R_sym(g0)
    print("start R", best_r, "N", N, "m", m)

    bounds = [(0.0, None)] * m

    def exact_polish(cur):
        def neg_R_grad(g):
            R, gr = R_grad_sym(g)
            return -R, -gr
        res = minimize(neg_R_grad, cur, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       options={'ftol': 1e-18, 'gtol': 1e-15,
                                'maxiter': 5000, 'maxcor': 40})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def topk_ladder(cur, Ks):
        for K in Ks:
            if time.process_time() > deadline:
                break

            def neg_topk_grad(g, _K=K):
                R, gr = R_topk_grad_sym(g, _K)
                return -R, -gr

            def callback(xk):
                if time.process_time() > deadline:
                    raise _Timeout()

            try:
                res = minimize(neg_topk_grad, cur, jac=True, method='L-BFGS-B',
                               bounds=bounds, callback=callback,
                               options={'ftol': 1e-18, 'gtol': 1e-15,
                                        'maxiter': 3000, 'maxcor': 40})
                cur = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    def try_update(cur, tag):
        nonlocal best_g, best_r
        r = R_sym(cur)
        if r > best_r:
            best_r = r
            best_g = cur.copy()
            print(tag, best_r)
            return True
        return False

    def flatten_plateau_g(g, tol=1e-3):
        h = h_of(g)
        L = _L(h)
        mx = float(np.max(L))
        if mx <= 0:
            return g
        mask = L >= (1.0 - tol) * mx
        hmask = np.zeros(N, dtype=bool)
        idx = np.where(mask)[0]
        for j in idx:
            if 1 <= j <= N:
                hmask[j - 1] = True
        if not hmask.any():
            return g
        out = h.copy()
        i = 0
        while i < N:
            if hmask[i]:
                j = i
                while j + 1 < N and hmask[j + 1]:
                    j += 1
                seg = out[i:j + 1]
                s = seg.sum()
                if s > 0:
                    out[i:j + 1] = s / seg.size
                i = j + 1
            else:
                i += 1
        out = 0.5 * (out + out[::-1])
        return np.maximum(out[:m], 0.0)

    TOGGLE_Ks = [min(k, N) for k in
                 [3200, 2640, 2080, 1600, 1200, 800, 480, 240, 120, 60, 32, 16, 8, 4]]
    TOGGLE_Ls = [2, 4, 6, 10, 16, 26, 42]

    def toggle_search(base_g):
        nonlocal best_g, best_r
        base_h = h_of(base_g)
        mask = base_h > 1e-8
        if mask.all() or not mask.any():
            return
        trans = np.where(mask[1:] != mask[:-1])[0] + 1
        if trans.size == 0:
            return
        cands = []
        hmax = float(np.max(base_h))
        for t in trans:
            for L in TOGGLE_Ls:
                if mask[t]:
                    lo = t; hi = min(N, t + L)
                else:
                    lo = max(0, t - L); hi = t
                if hi > lo:
                    c1 = base_h.copy()
                    c1[lo:hi] = 0.0
                    if np.any(c1 > 0):
                        cands.append(c1)
                if not mask[t]:
                    lo = t; hi = min(N, t + L)
                    if t > 0 and mask[t - 1]:
                        val = base_h[t - 1]
                    elif t < N and mask[t]:
                        val = base_h[t]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                else:
                    lo = max(0, t - L); hi = t
                    if hi < N and mask[hi]:
                        val = base_h[hi]
                    elif lo > 0 and mask[lo - 1]:
                        val = base_h[lo - 1]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                if len(cands) >= 40:
                    break
            if len(cands) >= 40:
                break

        best_c = None
        best_cr = best_r
        for cand in cands:
            if time.process_time() > deadline:
                break
            try:
                cg = 0.5 * (cand + cand[::-1])
                cg = np.maximum(cg[:m], 0.0)
                cx = topk_ladder(cg, TOGGLE_Ks)
                cx = exact_polish(cx)
                cr = R_sym(cx)
            except _Timeout:
                break
            except Exception:
                continue
            if cr > best_cr:
                best_cr = cr
                best_c = cx
        if best_c is not None:
            best_g = best_c.copy()
            best_r = best_cr
            print("toggle improved", best_r)

    try:
        cur = exact_polish(best_g)
        try_update(cur, "warm exact improved")
    except Exception:
        pass

    def plateau_penalty_polish(cur, lam):
        def neg_F_grad(g):
            R, gR = R_grad_sym(g)
            P, gP = plateau_penalty_grad_sym(g, tol=1e-3)
            F = -R + lam * P
            g = -gR + lam * gP
            return F, g

        def callback(xk):
            if time.process_time() > deadline:
                raise _Timeout()

        try:
            res = minimize(neg_F_grad, cur, jac=True, method='L-BFGS-B',
                           bounds=bounds, callback=callback,
                           options={'ftol': 1e-18, 'gtol': 1e-15,
                                    'maxiter': 2000, 'maxcor': 40})
            return np.maximum(np.asarray(res.x, dtype=float), 0.0)
        except _Timeout:
            raise
        except Exception:
            return cur

    for lam in (1e-3, 1e-2, 1e-1):
        if time.process_time() > deadline:
            break
        try:
            cand = plateau_penalty_polish(best_g.copy(), lam)
            cand = exact_polish(cand)
            try_update(cand, "plateau-var improved (lam=%g)" % lam)
        except _Timeout:
            break
        except Exception:
            pass

    for tol in (1e-2, 3e-3, 1e-3, 3e-4):
        if time.process_time() > deadline:
            break
        try:
            fg = flatten_plateau_g(best_g, tol)
            fg = topk_ladder(fg, [min(k, N) for k in
                                  [1600, 960, 640, 400, 200, 96, 48, 24, 12, 6, 3]])
            fg = exact_polish(fg)
            try_update(fg, "flatten improved (tol=%g)" % tol)
        except _Timeout:
            break
        except Exception:
            pass

    try:
        toggle_search(best_g.copy())
    except _Timeout:
        pass
    except Exception:
        pass

    Ks_big = [min(k, N) for k in
              [3200, 2640, 2080, 1600, 1200, 960, 800, 640, 480, 400, 320, 240, 200,
               160, 120, 100, 80, 60, 50, 40, 30, 25, 20, 15, 12, 10, 8, 7, 6, 5, 4, 3, 2]]

    rng = np.random.default_rng(20240611)
    cycle = 0
    no_improve = 0

    while time.process_time() < deadline:
        cycle += 1
        prev_r = best_r

        try:
            cur = topk_ladder(best_g.copy(), Ks_big)
            try_update(cur, "topk improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() > deadline:
            break
        try:
            cur = exact_polish(best_g.copy())
            try_update(cur, "exact improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() < deadline:
            for tol in (1e-2, 1e-3, 1e-4):
                if time.process_time() > deadline:
                    break
                try:
                    fg = flatten_plateau_g(best_g, tol)
                    fg = topk_ladder(fg, [min(k, N) for k in
