                    cx = cand
                    cr = R_sym(cand)
                if cr > best_trial_r:
                    best_trial_r = cr
                    best_trial = cx
            if best_trial_r > best_r:
                best_r = best_trial_r
                best_g = best_trial.copy()
                print("perturb improved", best_r, "cycle", cycle)
            no_improve = 0

    try:
        for tol in (3e-2, 2e-2, 1e-2, 5e-3, 3e-3, 1e-3, 3e-4, 1e-4):
            if time.process_time() > deadline:
