        pass
    except Exception:
        pass

    if R_sym(best_g) < R_sym(g0):
        best_g = g0.copy()
        best_r = R_sym(g0)

    result = h_of(best_g)
    assert len(result) == N
    assert np.allclose(result[:m], result[m:][::-1])

    print("final best R", best_r, "N", N, "m", m, "cycles", cycle)
    return result

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _L(h):
