    def _R_sym(g):
        return _R(h_of(g))

    def _R_grad_sym(g):
        h = h_of(g)
        R, gh = _R_grad(h)
        return R, gh[:m] + gh[m:][::-1]

    def _R_topk_grad_sym(g, K):
        h = h_of(g)
        R, gh = _R_topk_grad(h, K)
