                xt = np.linspace(0.0, 1.0, N)
                s_full = np.interp(xt, xs, s)
                s_full = np.maximum(s_full, 0.0)
            g0 = 0.5 * (s_full[:m] + s_full[::-1][:m])
        else:
            g0 = None
    else:
