            for tol in (1e-2, 1e-3, 1e-4):
                if time.process_time() > deadline:
                    break
                try:
                    fg = flatten_plateau_g(best_g, tol)
                    fg = topk_ladder(fg, [min(600, N), min(320, N), min(160, N),
                                          min(80, N), min(40, N), min(20, N), min(10, N), min(4, N)])
                    fg = exact_polish(fg)
                    try_update(fg, "flatten improved (tol=%g)" % tol)
                except _Timeout:
                    break
                except Exception:
                    pass

        if time.process_time() < deadline:
            try:
                toggle_search(best_g.copy())
            except _Timeout:
                break
            except Exception:
                pass

        if best_r <= prev_r + 1e-15:
            no_improve += 1
        else:
            no_improve = 0

        if no_improve >= 1 and time.process_time() < deadline:
            best_trial = best_g
            best_trial_r = best_r
            for scale in (1e-8, 1e-7, 3e-7, 1e-6, 3e-6):
                if time.process_time() > deadline:
                    break
                cand = best_g * np.exp(scale * rng.standard_normal(m))
                cand = np.maximum(cand, 1e-9)
                cand = cand * (np.sum(best_g) / np.sum(cand))
                try:
                    cx = topk_ladder(cand, [min(400, N), min(200, N), min(100, N),
                                            min(50, N), min(25, N), min(12, N), min(7, N), min(4, N)])
                    cx = exact_polish(cx)
                    cr = _R_sym(cx)
                except Exception:
                    cx = cand
                    cr = _R_sym(cand)
                if cr > best_trial_r:
                    best_trial_r = cr
                    best_trial = cx
            if best_trial_r > best_r:
                best_r = best_trial_r
                best_g = best_trial.copy()
                print("perturb improved", best_r, "cycle", cycle)
            no_improve = 0

    try:
        for tol in (3e-2, 2e-2, 1e-2, 5e-3, 3e-3, 1e-3, 3e-4, 1e-4):
            if time.process_time() > deadline:
                break
            fg = flatten_plateau_g(best_g, tol)
            fg = topk_ladder(fg, [min(480, N), min(240, N), min(120, N), min(60, N),
                                  min(30, N), min(15, N), min(8, N), min(4, N)])
            fg = exact_polish(fg)
            try_update(fg, "final flatten tol=%g" % tol)
    except _Timeout:
        pass
    except Exception:
        pass

    best_h = h_of(best_g)
    if _R(best_h) < _R(h_of(g0)):
        best_h = h_of(g0)
        best_g = g0.copy()
    best_r = _R(best_h)

    assert len(best_h) == N
    assert _R(best_h) >= _R(h_of(g0)) - 1e-12

    print("final best R", best_r, "N", N, "cycles", cycle)
    return best_h

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _L(h):
    c = fftconvolve(h, h)
    L = np.empty(c.size + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    return L


def _R(h):
    h = np.asarray(h, dtype=float)
    L = _L(h)
    a = L[:-1]; b = L[1:]
    l2sq = np.sum(a * a + a * b + b * b) / 3.0
    l1 = np.sum(h) ** 2
    linf = np.max(L)
    if l1 <= 0 or linf <= 0:
        return 0.0
    return l2sq / (l1 * linf)


def _R_grad(h):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    k = int(np.argmax(L))
    C = L[k]
    if B <= 0 or C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC = np.zeros_like(h)
    j = k - 1
    m = len(h)
    lo = max(0, j - (m - 1)); hi = min(m - 1, j)
    if lo <= hi:
        idx = np.arange(lo, hi + 1)
        dC[idx] = 2.0 * h[j - idx]
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _R_topk_grad(h, K):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    a = L[:-1]; b = L[1:]
    A = np.sum(a * a + a * b + b * b) / 3.0
    B = np.sum(h) ** 2
    if B <= 0 or A <= 0:
        return 0.0, np.zeros_like(h)
    K = min(K, L.size)
    idx = np.argpartition(L, -K)[-K:]
    C = np.mean(L[idx])
    if C <= 0:
        return 0.0, np.zeros_like(h)
    R = A / (B * C)
    g_c = (L[0:n] + 4.0 * L[1:n + 1] + L[2:n + 2]) / 3.0
    dA = 2.0 * fftconvolve(g_c, h[::-1], 'valid')
    dB = 2.0 * np.sum(h)
    dC_c = np.zeros(c.size)
    sel = idx[(idx >= 1) & (idx <= c.size)]
    dC_c[sel - 1] = 1.0 / K
    dC = 2.0 * fftconvolve(dC_c, h[::-1], 'valid')
    dlogR = dA / A - dB / B - dC / C
    return R, R * dlogR


def _plateau_penalty_grad(h, tol=1e-3):
    h = np.asarray(h, dtype=float)
    c = fftconvolve(h, h)
    n = c.size
    L = np.empty(n + 2)
    L[0] = 0.0
    L[-1] = 0.0
    L[1:-1] = c
    C = float(np.max(L))
    if C <= 0:
        return 0.0, np.zeros_like(h)
    mask = L >= (1.0 - tol) * C
    K = int(mask.sum())
    if K <= 1:
        return 0.0, np.zeros_like(h)
    Lm = L[mask]
    mean = Lm.mean()
    var = np.mean((Lm - mean) ** 2)
    P = var / (C * C)
    q = np.zeros_like(L)
    q[mask] = 2.0 * (Lm - mean) / K
    q_int = q[1:-1]
    dP = 2.0 * fftconvolve(q_int, h[::-1], 'valid')
    return P, dP


class _Timeout(Exception):
    pass


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 8000
    m = 4000

    def full(g):
        return np.concatenate([g, g[::-1]])

    def full_grad(g, gfun):
        # gfun(h) -> (val, grad_h) with grad_h length N; chain to g
        h = full(g)
        val, gh = gfun(h)
        gg = gh[:m] + gh[::-1][:m]
        return val, gg

    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.any(s > 0):
            if s.size == N:
                h0 = np.maximum(s.astype(float).copy(), 0.0)
            elif s.size == m:
                h0 = full(np.maximum(s.astype(float), 0.0))
            else:
                # piecewise-constant replication to length N
                idx = (np.arange(N) * s.size) // N
                h0 = np.maximum(s[idx].astype(float), 0.0)
        else:
            h0 = None
    else:
        h0 = None
    if h0 is None:
        g = np.array([min(i + 1, m - i) for i in range(m)], dtype=float)
        h0 = full(g)
    h0 = np.maximum(h0, 1e-9)
    if h0.sum() <= 0:
        h0 = np.ones(N)
    h0 = 0.5 * (h0 + h0[::-1])
    h0 = np.maximum(h0, 0.0)

    g0 = h0[:m].copy()
    g0 = np.maximum(g0, 1e-9)

    best_g = g0.copy()
    best_r = _R(full(g0))
    print("start R", best_r, "N", N, "m", m)

    bounds = [(0.0, None)] * m

    def obj_exact(g):
        return full_grad(g, _R_grad)

    def obj_topk(g, K):
        return full_grad(g, lambda h: _R_topk_grad(h, K))

    def obj_plateau(g, lam):
        def f(h):
            R, gR = _R_grad(h)
            P, gP = _plateau_penalty_grad(h, tol=1e-3)
            return -R + lam * P, -gR + lam * gP
        val, grad = full_grad(g, f)
        return val, grad

    def neg(fun):
        def f(g):
            v, gr = fun(g)
            return -v, -gr
        return f

    def exact_polish(cur):
        res = minimize(neg(obj_exact), cur, jac=True, method='L-BFGS-B',
                       bounds=bounds,
                       options={'ftol': 1e-18, 'gtol': 1e-15,
                                'maxiter': 5000, 'maxcor': 40})
        return np.maximum(np.asarray(res.x, dtype=float), 0.0)

    def topk_ladder(cur, Ks):
        for K in Ks:
            if time.process_time() > deadline:
                break

            def callback(xk):
                if time.process_time() > deadline:
                    raise _Timeout()

            try:
                res = minimize(neg(lambda g, _K=K: obj_topk(g, _K)), cur,
                               jac=True, method='L-BFGS-B',
                               bounds=bounds, callback=callback,
                               options={'ftol': 1e-18, 'gtol': 1e-15,
                                        'maxiter': 3000, 'maxcor': 40})
                cur = np.maximum(np.asarray(res.x, dtype=float), 0.0)
            except _Timeout:
                break
            except Exception:
                pass
        return cur

    def try_update(cur, tag):
        nonlocal best_g, best_r
        r = _R(full(cur))
        if r > best_r:
            best_r = r
            best_g = cur.copy()
            print(tag, best_r)
            return True
        return False

    def flatten_plateau(h, tol=1e-3):
        L = _L(h)
        mx = float(np.max(L))
        if mx <= 0:
            return h
        mask = L >= (1.0 - tol) * mx
        hmask = np.zeros_like(h, dtype=bool)
        idx = np.where(mask)[0]
        for j in idx:
            if 1 <= j <= h.size:
                hmask[j - 1] = True
        if not hmask.any():
            return h
        out = h.copy()
        i = 0
        n = h.size
        while i < n:
            if hmask[i]:
                j = i
                while j + 1 < n and hmask[j + 1]:
                    j += 1
                seg = out[i:j + 1]
                s = seg.sum()
                if s > 0:
                    out[i:j + 1] = s / seg.size
                i = j + 1
            else:
                i += 1
        return out

    def flatten_g(g, tol):
        h = flatten_plateau(full(g), tol)
        return np.maximum(h[:m], 0.0)

    TOGGLE_Ks = [min(3200, N), min(2640, N), min(2080, N), min(1600, N), min(1200, N),
                 min(800, N), min(480, N), min(240, N), min(120, N), min(64, N),
                 min(32, N), min(16, N), min(8, N)]
    TOGGLE_Ls = [4, 8, 12, 20, 32, 52, 84]

    def toggle_search(base_g):
        nonlocal best_g, best_r
        base_h = full(base_g)
        mask = base_h > 1e-8
        if mask.all() or not mask.any():
            return
        trans = np.where(mask[1:] != mask[:-1])[0] + 1
        if trans.size == 0:
            return
        cands = []
        hmax = float(np.max(base_h))
        for t in trans:
            for L in TOGGLE_Ls:
                if mask[t]:
                    lo = t; hi = min(N, t + L)
                else:
                    lo = max(0, t - L); hi = t
                if hi > lo:
                    c1 = base_h.copy()
                    c1[lo:hi] = 0.0
                    if np.any(c1 > 0):
                        cands.append(c1)
                if not mask[t]:
                    lo = t; hi = min(N, t + L)
                    if t > 0 and mask[t - 1]:
                        val = base_h[t - 1]
                    elif t < N and mask[t]:
                        val = base_h[t]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                else:
                    lo = max(0, t - L); hi = t
                    if hi < N and mask[hi]:
                        val = base_h[hi]
                    elif lo > 0 and mask[lo - 1]:
                        val = base_h[lo - 1]
                    else:
                        val = 1e-3 * hmax
                    c2 = base_h.copy()
                    c2[lo:hi] = val
                    cands.append(c2)
                if len(cands) >= 40:
                    break
            if len(cands) >= 40:
                break

        best_c = None
        best_cr = best_r
        for cand in cands:
            if time.process_time() > deadline:
                break
            try:
                cg = np.maximum(0.5 * (cand[:m] + cand[::-1][:m]), 0.0)
                cx = topk_ladder(cg, TOGGLE_Ks)
                cx = exact_polish(cx)
                cr = _R(full(cx))
            except _Timeout:
                break
            except Exception:
                continue
            if cr > best_cr:
                best_cr = cr
                best_c = cx
        if best_c is not None:
            best_g = best_c.copy()
            best_r = best_cr
            print("toggle improved", best_r)

    try:
        cur = exact_polish(best_g)
        try_update(cur, "warm exact improved")
    except Exception:
        pass

    def plateau_penalty_polish(cur, lam):
        def callback(xk):
            if time.process_time() > deadline:
                raise _Timeout()

        try:
            res = minimize(neg(lambda g, _l=lam: obj_plateau(g, _l)), cur,
                           jac=True, method='L-BFGS-B',
                           bounds=bounds, callback=callback,
                           options={'ftol': 1e-18, 'gtol': 1e-15,
                                    'maxiter': 2000, 'maxcor': 40})
            return np.maximum(np.asarray(res.x, dtype=float), 0.0)
        except _Timeout:
            raise
        except Exception:
            return cur

    for lam in (1e-3, 1e-2, 1e-1):
        if time.process_time() > deadline:
            break
        try:
            cand = plateau_penalty_polish(best_g.copy(), lam)
            cand = exact_polish(cand)
            try_update(cand, "plateau-var improved (lam=%g)" % lam)
        except _Timeout:
            break
        except Exception:
            pass

    for tol in (1e-2, 3e-3, 1e-3, 3e-4):
        if time.process_time() > deadline:
            break
        try:
            fg = flatten_g(best_g, tol)
            fg = topk_ladder(fg, [min(1600, N), min(960, N), min(640, N), min(400, N),
                                  min(200, N), min(96, N), min(48, N), min(24, N), min(12, N), min(6, N)])
            fg = exact_polish(fg)
            try_update(fg, "flatten improved (tol=%g)" % tol)
        except _Timeout:
            break
        except Exception:
            pass

    try:
        toggle_search(best_g.copy())
    except _Timeout:
        pass
    except Exception:
        pass

    Ks_big = [min(k, N) for k in
              [3200, 2640, 2080, 1600, 1200, 960, 800, 640, 480, 400, 320, 240, 200,
               160, 120, 100, 80, 60, 50, 40, 30, 24, 20, 16, 14, 12, 10, 8, 6, 4]]

    rng = np.random.default_rng(20240611)
    cycle = 0
    no_improve = 0

    while time.process_time() < deadline:
        cycle += 1
        prev_r = best_r

        try:
            cur = topk_ladder(best_g.copy(), Ks_big)
            try_update(cur, "topk improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() > deadline:
            break
        try:
            cur = exact_polish(best_g.copy())
            try_update(cur, "exact improved")
        except _Timeout:
            break
        except Exception:
            pass

        if time.process_time() < deadline:
            for tol in (1e-2, 1e-3, 1e-4):
                if time.process_time() > deadline:
                    break
                try:
                    fg = flatten_g(best_g, tol)
                    fg = topk_ladder(fg, [min(1200, N), min(640, N), min(320, N),
                                          min(160, N), min(80, N), min(40, N), min(20, N), min(8, N)])
                    fg = exact_polish(fg)
                    try_update(fg, "flatten improved (tol=%g)" % tol)
                except _Timeout:
                    break
                except Exception:
                    pass

        if time.process_time() < deadline:
            try:
                toggle_search(best_g.copy())
            except _Timeout:
                break
            except Exception:
                pass

        if best_r <= prev_r + 1e-15:
            no_improve += 1
        else:
            no_improve = 0

        if no_improve >= 1 and time.process_time() < deadline:
            best_trial = best_g
            best_trial_r = best_r
            for scale in (1e-8, 1e-7, 3e-7, 1e-6, 3e-6):
                if time.process_time() > deadline:
                    break
                cand = best_g * np.exp(scale * rng.standard_normal(m))
                cand = np.maximum(cand, 1e-9)
                cand = cand * (np.sum(best_g) / np.sum(cand))
                try:
                    cx = topk_ladder(cand, [min(800, N), min(400, N), min(200, N),
                                            min(100, N), min(50, N), min(24, N), min(14, N), min(8, N)])
                    cx = exact_polish(cx)
                    cr = _R(full(cx))
                except Exception:
                    cx = cand
                    cr = _R(full(cand))
                if cr > best_trial_r:
                    best_trial_r = cr
                    best_trial = cx
            if best_trial_r > best_r:
                best_r = best_trial_r
                best_g = best_trial.copy()
                print("perturb improved", best_r, "cycle", cycle)
            no_improve = 0

    try:
        if time.process_time() < deadline:
            sym = 0.5 * (best_g + best_g[::-1])
            sym = np.maximum(sym, 0.0)
            if sym.sum() > 0:
                sym = topk_ladder(sym, [min(1600, N), min(960, N), min(640, N),
                                        min(400, N), min(200, N), min(96, N),
                                        min(48, N), min(24, N), min(12, N), min(6, N)])
                sym = flatten_g(sym, 1e-2)
                sym = exact_polish(sym)
                sr = _R(full(sym))
                if sr > best_r:
                    best_r = sr
                    best_g = sym.copy()
                    print("final symmetrize improved", best_r)
                else:
                    print("final symmetrize no gain", sr, "vs", best_r)
    except _Timeout:
        pass
    except Exception:
        pass

    try:
        for tol in (3e-2, 2e-2, 1e-2, 5e-3, 3e-3, 1e-3, 3e-4, 1e-4):
            if time.process_time() > deadline:
                break
            fg = flatten_g(best_g, tol)
            fg = topk_ladder(fg, [min(960, N), min(480, N), min(240, N), min(120, N),
                                  min(60, N), min(30, N), min(16, N), min(8, N)])
            fg = exact_polish(fg)
            try_update(fg, "final flatten tol=%g" % tol)
    except _Timeout:
        pass
    except Exception:
        pass

    if _R(full(best_g)) < _R(full(g0)):
        best_g = g0.copy()
        best_r = _R(full(g0))

    best_h = full(best_g)
    assert len(best_h) == N
    assert _R(best_h) >= _R(full(g0)) - 1e-12

    print("final best R", best_r, "N", N, "m", m, "cycles", cycle)
    return best_h
